import{_t as e,et as t,it as n,n as r,rt as i}from"./chunks/framework.C6TizvAB.js";var a=JSON.parse(`{"title":"中美火箭回收有何异同","description":"SpaceX目前有两款型号，一个是成熟运行10年的猎鹰9号；一个是试验阶段的星舰。中国目前测试成功的型号是长征十号-乙。本文列举三者的参数。","frontmatter":{"title":"中美火箭回收有何异同","description":"SpaceX目前有两款型号，一个是成熟运行10年的猎鹰9号；一个是试验阶段的星舰。中国目前测试成功的型号是长征十号-乙。本文列举三者的参数。","date":"2026-07-12T00:00:00.000Z","category":"置身事内","tags":["企业观察"],"order":8},"headers":[],"relativePath":"articles/zstn/firm/huojianhuishou.md","filePath":"articles/zstn/firm/huojianhuishou.md","articleMeta":{"updated":"2026-07-12","words":2931,"minutes":7}}`),o={name:`articles/zstn/firm/huojianhuishou.md`};function s(r,a,o,s,c,l){return e(),i(`div`,null,[...a[0]||=[n(`<h2 id="火箭回收方案对比" tabindex="-1">火箭回收方案对比 <a class="header-anchor" href="#火箭回收方案对比" aria-label="Permalink to “火箭回收方案对比”">​</a></h2><p>博主整理，如有错误，欢迎指正。</p><table tabindex="0"><thead><tr><th></th><th style="text-align:left;">猎鹰9 (Falcon 9)</th><th>星舰 (Starship)</th><th>长征十号乙 (CZ-10B)</th></tr></thead><tbody><tr><td>发展阶段</td><td style="text-align:left;">量产</td><td>试验阶段</td><td>试验阶段</td></tr><tr><td>回收能力</td><td style="text-align:left;">仅一级回收</td><td><strong>全部可回收</strong></td><td>仅一级回收</td></tr><tr><td>回收形式</td><td style="text-align:left;">着陆腿</td><td>塔架机械臂（“筷子”）</td><td>海上平台网系捕获（“大网抱住”）</td></tr><tr><td>复用次数</td><td style="text-align:left;">设计复用10次。最高纪录：36次</td><td>暂无</td><td>暂无</td></tr><tr><td>最快周转时间</td><td style="text-align:left;">10天</td><td>暂无记录</td><td>暂无记录</td></tr><tr><td>首次成功时间</td><td style="text-align:left;"><strong>2015年</strong></td><td>2024年</td><td>2026年</td></tr><tr><td>近地运载量</td><td style="text-align:left;">22.8吨</td><td>100 ~ 150 吨（全复用状态）</td><td>16吨</td></tr><tr><td>自重</td><td style="text-align:left;">549吨</td><td>约 5000 吨</td><td>约 760 吨</td></tr><tr><td>大小</td><td style="text-align:left;">70米，直径3.7米</td><td>124米，直径9米</td><td>70米，直径5米</td></tr></tbody></table><h3 id="几个观点" tabindex="-1">几个观点： <a class="header-anchor" href="#几个观点" aria-label="Permalink to “几个观点：”">​</a></h3><h4 id="_1-猎鹰9号vs长征十号乙-技术代差10年" tabindex="-1">1. 猎鹰9号vs长征十号乙，技术代差10年 <a class="header-anchor" href="#_1-猎鹰9号vs长征十号乙-技术代差10年" aria-label="Permalink to “1.  猎鹰9号vs长征十号乙，技术代差10年”">​</a></h4><p>中国在2026年7月实现了火箭一级回收，而马斯克的猎鹰9号飞船在2025年实现了一级火箭陆地回收、2016年实现海上无人船回收，而猎鹰9号和长征十号乙的运载能力接近，所以可以粗算我国和美国的技术差了10年，整整一代。</p><h4 id="_2-星舰仍是遥不可及的怪兽" tabindex="-1">2. 星舰仍是遥不可及的怪兽 <a class="header-anchor" href="#_2-星舰仍是遥不可及的怪兽" aria-label="Permalink to “2. 星舰仍是遥不可及的怪兽”">​</a></h4><p>星舰仍遥遥领先。首先，星舰拥有怪兽级的运载量，其起飞重量约 5000 吨，起飞推力超 7000 吨；一枚星舰的起飞重量相当于将近 7 枚长十乙叠加；近地运载能力也将近10倍。其次是回收能力上，星舰实现了 <strong>全箭完全重复使用</strong> ，不仅第一级超重型助推器要收回来，第二级星舰飞船在绕地轨道飞行或执行完任务后，也实现了再入大气层的高温整体返回；目前长十乙仅回收一级。</p><h2 id="一、猎鹰9号" tabindex="-1">一、猎鹰9号 <a class="header-anchor" href="#一、猎鹰9号" aria-label="Permalink to “一、猎鹰9号”">​</a></h2><h3 id="主要参数" tabindex="-1">主要参数 <a class="header-anchor" href="#主要参数" aria-label="Permalink to “主要参数”">​</a></h3><p><img src="https://static.wyclab.com/image-20260712152439556260712.png" alt="image-20260712152439556"></p><h3 id="回收技术细节" tabindex="-1">回收技术细节 <a class="header-anchor" href="#回收技术细节" aria-label="Permalink to “回收技术细节”">​</a></h3><p>猎鹰9号底部配有 <strong>4个</strong> 由高强度碳纤维和蜂窝铝制成的<strong>对称着陆腿</strong>。</p><p><strong>着陆前</strong>：在距离地面或海上驳船着陆点仅剩 <strong>约10秒</strong>、高度约数百米时，系统利用高压氦气作为动力，将其向外向下拉开。</p><p><strong>着陆后</strong>：着陆腿内部带有先进的<strong>液压减震系统</strong>，用于吸收火箭触地瞬间的巨大冲击力。</p><p>猎鹰九号可以实现陆地垂直着陆（RTLS）和海上自主驳船着陆（ASDS）。</p><p><img src="https://static.wyclab.com/falcon-9-reusable-landing-leg-configuration-v0-AoYkqGiLKjv59EJuN1XsvY57_rAaXaMrXUaRN5bfP5g260712.png" alt="猎鹰9号可重复使用着陆腿配置: r/space"></p><p><strong>陆地回收（RTLS）</strong>：火箭需要预留大量燃料在空中逆向减速复位，这会使火箭运力缩水 <strong>约 30%</strong>。</p><p><img src="https://static.wyclab.com/image-20260712155934224260712.png" alt="image-20260712155934224"></p><p><strong>海上回收（ASDS）</strong>：火箭完全顺着抛物线惯性下落，只在最后 20 秒点火一次进行软着陆。虽然多花了几十万美元的船舶运营费，却<strong>释放了近 3 吨的黄金运载量</strong>。</p><p><img src="https://static.wyclab.com/images260712.jpeg" alt="猎鹰九号海面回收"></p><p>ASDS 并不是普通的货船，它们由大型钢制甲板驳船（Marmac 300系列）深度改装而成。<strong>尺寸与面积</strong>：船身长约 <strong>91米</strong>，宽约 <strong>30米</strong>。为了给火箭着陆腿留足空间，SpaceX 在两侧加装了扩展翼，使实际可着陆宽度达到了 <strong>52米</strong>。<strong>耐高温甲板</strong>：火箭在降落最后一秒会直接用梅林发动机的高温烈焰对冲甲板。因此，整个甲板涂满了特制的<strong>耐高温非刮擦防滑涂层</strong>，并配备了消防与冷却喷淋系统。</p><h3 id="视频" tabindex="-1">视频 <a class="header-anchor" href="#视频" aria-label="Permalink to “视频”">​</a></h3>`,23),t(`iframe`,{width:`100%`,height:`468`,src:`//player.bilibili.com/player.html?isOutside=true&aid=270705073&bvid=BV12c411T7PK&cid=1114646998&p=1`,scrolling:`no`,border:`0`,frameborder:`no`,framespacing:`0`,allowfullscreen:`true`},null,-1),n(`<h2 id="二、星舰技术细节" tabindex="-1">二、星舰技术细节 <a class="header-anchor" href="#二、星舰技术细节" aria-label="Permalink to “二、星舰技术细节”">​</a></h2><p>SpaceX 正在测试的下一代巨型火箭 <strong>“星舰”（Starship）</strong>。</p><h3 id="主要参数-1" tabindex="-1">主要参数 <a class="header-anchor" href="#主要参数-1" aria-label="Permalink to “主要参数”">​</a></h3><p><img src="https://static.wyclab.com/image-20260712152903038260712.png" alt="image-20260712152903038"></p><h3 id="回收技术细节-1" tabindex="-1">回收技术细节 <a class="header-anchor" href="#回收技术细节-1" aria-label="Permalink to “回收技术细节”">​</a></h3><p>返场时完全依赖发射塔上的巨大机械臂（被称为“筷子” Mechazilla）在半空中直接<strong>夹住</strong>火箭。省去着陆腿的硬件重量（2吨）。</p><p><img src="https://static.wyclab.com/MBXY-CR-bc4e99f4e53295ad09d031f7b3feb48e260712.png" alt="img"></p><h3 id="视频-1" tabindex="-1">视频 <a class="header-anchor" href="#视频-1" aria-label="Permalink to “视频”">​</a></h3>`,8),t(`iframe`,{width:`100%`,height:`468`,src:`//player.bilibili.com/player.html?isOutside=true&aid=113300146817640&bvid=BV1LY2BYZEQi&cid=26275024453&p=1`,scrolling:`no`,border:`0`,frameborder:`no`,framespacing:`0`,allowfullscreen:`true`},null,-1),n(`<h2 id="三、长征十号乙" tabindex="-1">三、长征十号乙 <a class="header-anchor" href="#三、长征十号乙" aria-label="Permalink to “三、长征十号乙”">​</a></h2><h3 id="基本参数" tabindex="-1">基本参数 <a class="header-anchor" href="#基本参数" aria-label="Permalink to “基本参数”">​</a></h3><p>全箭长度63.6米，后续可以拓展到70米，5米直径，起飞重量约760吨。长征十号乙在回收状态下，近地200公里轨道运载能力为16吨。7台发动机并联，2台固定，5台可以摇摆，可以二次启动。级间段配备栅格舵，在回收过程中就像一个方向盘。一个人字形的“挂钩”，可以钩住“大网”实现回收</p><h3 id="回收细节" tabindex="-1">回收细节 <a class="header-anchor" href="#回收细节" aria-label="Permalink to “回收细节”">​</a></h3><p><img src="https://static.wyclab.com/MBXY-CR-fe35c7c5e082c6011e5216cb34efb6d2260712.jpeg" alt="img"></p><h3 id="视频-2" tabindex="-1">视频 <a class="header-anchor" href="#视频-2" aria-label="Permalink to “视频”">​</a></h3>`,6),t(`iframe`,{width:`100%`,height:`468`,src:`//player.bilibili.com/player.html?isOutside=true&aid=116898977027763&bvid=BV1kiNs6pEW5&cid=39852509448&p=1`,scrolling:`no`,border:`0`,frameborder:`no`,framespacing:`0`,allowfullscreen:`true`},null,-1)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};